data.setupCode:
// Word lists. Pick one with the "Lyrics" param; edit them or add your own here
// (keep the Lyrics param options in the same order as these names).
state.sets = {
  'Feel the beat': ['FEEL', 'THE', 'BEAT', 'MOVE', 'YOUR', 'BODY', 'ALL', 'NIGHT', 'LONG'],
  'Neon nights': ['NEON', 'NIGHTS', 'CITY', 'LIGHTS', 'NEVER', 'SLEEP'],
  'Hold on': ['HOLD', 'ON', 'TO', 'THE', 'LIGHT'],
  'Countdown': ['3', '2', '1', 'GO!'],
};
state.setNames = Object.keys(state.sets);
// The "Font" param options, as CSS fonts ({size} is replaced)
state.fonts = [
  '900 {size}px "Arial Black", "Helvetica Neue", Impact, sans-serif',
  'italic 700 {size}px Georgia, "Times New Roman", serif',
  '700 {size}px "SF Mono", Menlo, Consolas, monospace',
];
state.c = canvas(1024, 512);
state.g = state.c.getContext('2d');
// Draw a word into three channels: G = blurred glow, R = crisp fill, B = outline
state.draw = (word, font, size) => {
  const g = state.g, W = 1024, H = 512;
  g.globalCompositeOperation = 'source-over';
  g.filter = 'none';
  g.fillStyle = '#000';
  g.fillRect(0, 0, W, H);
  g.font = font.replace('{size}', size);
  const s = Math.round(Math.min(size, size * 920 / Math.max(g.measureText(word).width, 1))); // long words shrink to fit
  g.font = font.replace('{size}', s);
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  const y = H / 2 + s * 0.04;
  g.globalCompositeOperation = 'lighter';
  g.filter = 'blur(18px)';
  g.fillStyle = '#00ff00';
  g.fillText(word, W / 2, y);
  g.filter = 'none';
  g.fillStyle = '#ff0000';
  g.fillText(word, W / 2, y);
  g.lineWidth = Math.max(2, s * 0.025);
  g.strokeStyle = '#0000ff';
  g.strokeText(word, W / 2, y);
};

data.code:
// A new word on every beat (audio.beatCount: metronome, mic or music file; it free-runs
// when the audio is off). The canvas is redrawn, and re-uploaded to the GPU, only when
// the word, the list, the font or the size changes.
const words = state.sets[state.setNames[params['Lyrics'] | 0] || state.setNames[0]];
// While the beat clock is unsure (a track change: audio.trust = u_beatTrust low) the word
// holds, so words don't change on beats that aren't in the music (trust is 1 without live audio)
if (state.n === undefined || (audio.trust ?? 1) >= 0.5) state.n = Math.floor(audio.beatCount);
const n = state.n;
const word = words[((n % words.length) + words.length) % words.length];
const font = state.fonts[params['Font'] | 0] || state.fonts[0];
const size = Math.round(params['Font size'] ?? 170);
const key = `${word}|${font}|${size}`;
if (key !== state.key) {
  state.key = key;
  state.draw(word, font, size);
}
// Beat punch: full strength once the beat is locked (confidence 1 with the metronome)
const pulse = audio.beat * (params['Beat punch'] ?? 1) * (0.35 + 0.65 * audio.confidence);
// Each word gets the next hue
const hue = ((params['Base hue'] ?? 0.85) + n * (params['Hue step'] ?? 0.13)) % 1;
return { words: state.c, pulse: float(pulse), hue: float(hue) };

LyricWarp.customGLSL:
// @node lyricWarp
// @title Lyric Warp
// @category custom
// @description Warps the JS word canvas (R = crisp fill, G = blurred glow, B = outline) with layered sine ripples, punches in and splits it into RGB on the beat, adds an outline echo that grows over each beat, and keeps fading trails of the previous frame (prev = Feedback.out of this node's own output). Returns the light layer (HDR, no background).
vec3 lw_hue(float h) {
    vec3 k = clamp(abs(fract(h + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return mix(vec3(1.0), k, 0.75);
}

vec3 lyricWarp(vec2 uv, sampler2D words, sampler2D prev, float pulse, float hue, float warp, float glow, float split, float trails) {
    float aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    float t = u_time;
    // Punch in on the beat
    p *= 1.0 - 0.09 * pulse;
    // Liquid warp: two sine layers per axis
    vec2 w = vec2(sin(p.y * 6.0 + t * 1.6) + 0.5 * sin(p.y * 15.0 - t * 2.7 + p.x * 3.0),
                  sin(p.x * 4.0 - t * 1.2) + 0.5 * sin(p.x * 11.0 + t * 2.1));
    p += warp * (0.012 + 0.025 * pulse) * w;
    // The 2:1 word canvas spans 1.7 units, centred
    vec2 q = p / vec2(1.7, 0.85) + 0.5;
    // Chromatic split, wider on the beat
    vec2 off = split * (0.0025 + 0.012 * pulse) * vec2(1.0, 0.2);
    vec3 ink = vec3(texture(words, q + off).r, texture(words, q).r, texture(words, q - off).r);
    float halo = texture(words, q).g;
    // Outline echo: grows and fades over each beat
    float ph = u_beatPhase;
    vec2 qe = (q - 0.5) / (1.0 + 0.35 * ph) + 0.5;
    float echo = texture(words, qe).b * (1.0 - ph) * (1.0 - ph) * smoothstep(0.25, 0.75, u_beatTrust); // fades while the beat clock is unsure
    vec3 c1 = lw_hue(hue);
    vec3 c2 = lw_hue(hue + 0.12);
    vec3 cur = ink * mix(vec3(1.0), c1, 0.35) * (0.85 + 0.6 * pulse)
             + halo * c1 * c1 * glow * (0.5 + 0.8 * pulse)
             + echo * c2 * c2 * 0.7 * glow;
    // Trails: last frame's light, zoomed out a hair, drifting and cooling
    vec2 pu = 0.5 + (uv - 0.5) * 0.988 + 0.0015 * vec2(sin(t * 0.7), cos(t * 0.9));
    vec3 old = texture(prev, pu).rgb * trails * vec3(0.96, 0.93, 1.0);
    return max(cur, old);
}

LyricStage.customGLSL:
// @node lyricStage
// @title Lyric Stage
// @category custom
// @description Stage for the lyric light layer: a deep violet backdrop with a spotlight in the word colour that swells on the beat, light rays (a radial smear of last frame's light, prev = the trail Feedback), a rippled floor reflection and a scrolling perspective grid below the horizon and fine scanlines. Adds the light layer on top (HDR, tonemap afterwards).
vec3 ls_hue(float h) {
    vec3 k = clamp(abs(fract(h + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return mix(vec3(1.0), k, 0.75);
}

vec3 lyricStage(vec2 uv, vec3 light, sampler2D prev, float pulse, float hue, float rays, float reflection) {
    float aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    vec3 c1 = ls_hue(hue);
    vec3 bg = mix(vec3(0.010, 0.006, 0.026), vec3(0.05, 0.014, 0.08), smoothstep(0.0, 1.0, uv.y));
    bg += c1 * 0.10 * exp(-dot(p, p) * 2.2) * (0.5 + 0.9 * pulse);
    // Light rays: last frame's light smeared toward the centre
    vec3 ray = vec3(0.0);
    for (int i = 1; i <= 12; i++) {
        float k = float(i) / 12.0;
        ray += texture(prev, mix(uv, vec2(0.5), k * 0.4)).rgb * (1.0 - k) * c1;
    }
    ray *= 0.035 * rays * (0.7 + 0.6 * pulse);
    // Wet floor: a rippled mirror image of the light below the horizon
    float hz = 0.37;
    vec3 refl = vec3(0.0);
    if (uv.y < hz) {
        float depth = (hz - uv.y) / hz;
        vec2 ru = vec2(uv.x + 0.006 * depth * sin(uv.y * 160.0 + u_time * 3.0), 2.0 * hz - uv.y);
        refl = texture(prev, ru).rgb * reflection * 0.3 * (1.0 - depth) * (1.0 - depth);
        // Perspective floor grid scrolling toward the viewer, brighter on the beat
        float fz = 0.1 / max(hz - uv.y, 0.002);
        vec2 gp = vec2(p.x * fz * 9.0, fz * 3.0 + u_time * 1.5);
        vec2 gd = abs(fract(gp) - 0.5);
        vec2 gw = fwidth(gp) * 1.5;
        float line = max(1.0 - smoothstep(vec2(0.0), gw, 0.5 - gd).x, 1.0 - smoothstep(0.0, gw.y, 0.5 - gd.y));
        float fade = smoothstep(0.0, 0.3, depth) * (1.0 - depth * 0.5);
        bg += c1 * c1 * line * fade * (0.14 + 0.22 * pulse);
        bg += c1 * 0.02 * (1.0 - depth);
    }
    float scan = 0.93 + 0.07 * sin(uv.y * u_resolution.y * 1.6);
    return (bg + light + ray + refl) * scan;
}
